## Database Session Dependency (SQLAlchemy)

```python
from sqlalchemy.orm import Session
from database import SessionLocal

def get_db():
    db = SessionLocal()
    try:
        yield db          # Provide the session
    finally:
        db.close()        # Cleanup — runs after response is sent

# Usage in route
@app.get('/users/{user_id}')
def get_user(user_id: int, db: Session = Depends(get_db)):
    return db.query(User).filter(User.id == user_id).first()
```

## Auth Dependency Chain

```python
from fastapi import Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer
import jwt

oauth2_scheme = OAuth2PasswordBearer(tokenUrl='/auth/login')

def get_current_user(
    token: str = Depends(oauth2_scheme),
    db: Session = Depends(get_db)
) -> User:
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=['HS256'])
        user_id = payload.get('sub')
    except jwt.InvalidTokenError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail='Invalid token',
            headers={'WWW-Authenticate': 'Bearer'},
        )
    user = db.query(User).filter(User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=401, detail='User not found')
    return user

def get_admin_user(current_user: User = Depends(get_current_user)) -> User:
    if not current_user.is_admin:
        raise HTTPException(status_code=403, detail='Admin access required')
    return current_user

# Route using both
@app.delete('/users/{user_id}')
def delete_user(
    user_id: int,
    admin: User = Depends(get_admin_user),
    db: Session = Depends(get_db)
):
    db.query(User).filter(User.id == user_id).delete()
    db.commit()
    return {'deleted': user_id}
```

## Testing with Dependency Override

```python
from fastapi.testclient import TestClient

def override_get_db():
    db = TestSessionLocal()
    try:
        yield db
    finally:
        db.close()

def override_current_user():
    return User(id=1, email='test@test.com', is_admin=True)

app.dependency_overrides[get_db] = override_get_db
app.dependency_overrides[get_current_user] = override_current_user

client = TestClient(app)
# All routes now use test DB and fake auth
```

## Three Model Pattern (Input / Output / DB)

```python
from pydantic import BaseModel, field_validator, model_validator, EmailStr
from typing import Optional
import re

# Input: what we accept from the client
class UserCreate(BaseModel):
    email: EmailStr
    password: str
    confirm_password: str
    phone: Optional[str] = None

    @field_validator('password')
    @classmethod
    def password_strength(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError('Password must be at least 8 characters')
        if not re.search(r'[A-Z]', v):
            raise ValueError('Password must contain an uppercase letter')
        if not re.search(r'\d', v):
            raise ValueError('Password must contain a digit')
        return v

    @field_validator('phone')
    @classmethod
    def phone_format(cls, v: Optional[str]) -> Optional[str]:
        if v is not None:
            cleaned = re.sub(r'\D', '', v)
            if len(cleaned) not in (10, 11):
                raise ValueError('Phone must be 10 or 11 digits')
            return cleaned
        return v

    @model_validator(mode='after')
    def passwords_match(self) -> 'UserCreate':
        if self.password != self.confirm_password:
            raise ValueError('Passwords do not match')
        return self

# Output: what we expose to the client (never expose password_hash)
class UserOut(BaseModel):
    id: int
    email: str
    phone: Optional[str]
    is_active: bool

    class Config:
        from_attributes = True  # Pydantic v2: read from ORM object attributes

# Route
@app.post('/users', response_model=UserOut, status_code=201)
async def create_user(user_in: UserCreate, db: AsyncSession = Depends(get_db)):
    user = User(
        email=user_in.email,
        password_hash=hash_password(user_in.password),
        phone=user_in.phone,
    )
    db.add(user)
    await db.commit()
    await db.refresh(user)
    return user  # Pydantic serializes using UserOut model
```

## Custom Error Handling

```python
from fastapi import Request
from fastapi.responses import JSONResponse
from pydantic import ValidationError

@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc):
    return JSONResponse(
        status_code=422,
        content={
            'detail': 'Validation failed',
            'errors': [
                {
                    'field': '.'.join(str(loc) for loc in err['loc']),
                    'message': err['msg'],
                    'type': err['type'],
                }
                for err in exc.errors()
            ],
        },
    )
```
